class MinPriorityQueue {
    private heap: { dist: number, node: string }[] = [];

    insert(dist: number, node: string): void {
        this.heap.push({ dist, node });
        this.bubbleUp(this.heap.length - 1);
    }

    extractMin(): { dist: number, node: string } | undefined {
        if (this.isEmpty()) {
            return undefined;
        }
        if (this.heap.length === 1) {
            return this.heap.pop();
        }
        const min = this.heap[0];
        this.heap.shift();
        this.bubbleDown(0);
        return min;
    }

    isEmpty(): boolean {
        return this.heap.length === 0;
    }

    private bubbleUp(index: number): void {
        while (index > 0) {
            const parentIndex = Math.floor((index - 1) / 2);
            if (this.heap[index].dist < this.heap[parentIndex].dist) {
                [this.heap[index], this.heap[parentIndex]] = [this.heap[parentIndex], this.heap[index]];
                index = parentIndex;
            } else {
                break;
            }
        }
    }

    private bubbleDown(index: number): void {
        const lastIndex = this.heap.length - 1;
        while (true) {
            let smallest = index;
            const left = 2 * index + 1;
            const right = 2 * index + 2;

            if (left <= lastIndex && this.heap[left].dist < this.heap[smallest].dist) {
                smallest = left;
            }
            if (right <= lastIndex && this.heap[right].dist < this.heap[smallest].dist) {
                smallest = right;
            }

            if (smallest !== index) {
                [this.heap[index], this.heap[smallest]] = [this.heap[smallest], this.heap[index]];
                index = smallest;
            } else {
                break;
            }
        }
    }
}

function dijkstra(graph: Record<string, Array<{node: string, weight: number}>>, startNode: string, targetNode: string): { distances: Record<string, number>, path: string[] } {
    const distances: Record<string, number> = {};
    const predecessors: Record<string, string | null> = {};
    const pq = new MinPriorityQueue();

    // Initialization
    for (const node in graph) {
        distances[node] = Infinity;
        predecessors[node] = null;
    }
    distances[startNode] = 0;
    pq.insert(0, startNode);

    // Dijkstra's core loop
    while (!pq.isEmpty()) {
        const { dist: currentDist, node: currentNode } = pq.extractMin()!;

        if (currentDist > distances[currentNode]) {
            continue;
        }

        if (currentNode === targetNode) {
            break;
        }

        if (graph[currentNode]) {
            for (const edge of graph[currentNode]) {
                const neighbor = edge.node;
                const weight = edge.weight;
                const newDist = currentDist + weight;

                if (newDist < distances[neighbor]!) {
                    distances[neighbor] = newDist;
                    predecessors[neighbor] = currentNode;
                    pq.insert(newDist, neighbor);
                }
            }
        }
    }

    // Path reconstruction
    const path: string[] = [];
    let current = targetNode;
    if (distances[targetNode] === Infinity) {
        return { distances, path: [] }; // Target unreachable
    }

    while (current !== null) {
        path.unshift(current);
        current = predecessors[current];
        if (current === startNode) {
            path.unshift(startNode);
            break;
        }
    }

    return { distances, path };
}

