public class BoundedBlockingQueue<E> {

    private final Queue<E> queue;
    private final int capacity;
    private final ReentrantLock lock;
    private final Condition notFull;
    private final Condition notEmpty;

    public BoundedBlockingQueue(int capacity) {
        this.capacity = capacity;
        this.queue = new LinkedList<>();
        this.lock = new ReentrantLock();
        this.notFull = lock.newCondition();
        this.notEmpty = lock.newCondition();
    }

    public void put(E item) throws InterruptedException {
        lock.lock();
        try {
            while (queue.size() == capacity) {
                System.out.println(Thread.currentThread().getName() + " waiting: Queue is full.");
                notFull.await();
            }
            queue.add(item);
            System.out.println(Thread.currentThread().getName() + " put: " + item + ". Queue size: " + queue.size());
            notEmpty.signal();
        } finally {
            lock.unlock();
        }
    }

    public E take() throws InterruptedException {
        lock.lock();
        try {
            while (queue.isEmpty()) {
                System.out.println(Thread.currentThread().getName() + " waiting: Queue is empty.");
                notEmpty.await();
            }
            E item = queue.poll();
            System.out.println(Thread.currentThread().getName() + " took: " + item + ". Queue size: " + queue.size());
            notFull.signal();
            return item;
        } finally {
            lock.unlock();
        }
    }

