class PriorityQueue<T> {
    private heap: { priority: number, value: T }[] = [];

    enqueue(value: T, priority: number): void {
        this.heap.push({ priority, value });
        this.bubbleUp(this.heap.length - 1);
    }

    dequeue(): { priority: number, value: T } | undefined {
        if (this.isEmpty()) {
            return undefined;
        }
        const min = this.heap[0];
        this.heap.splice(0, 1);
        this.sinkDown(0);
        return min;
    }

    isEmpty(): boolean {
        return this.heap.length === 0;
    }

    private bubbleUp(index: number): void {
        while (index > 0) {
            const parentIndex = Math.floor((index - 1) / 2);
            if (this.heap[index].priority < this.heap[parentIndex].priority) {
                [this.heap[index], this.heap[parentIndex]] = [this.heap[parentIndex], this.heap[index]];
                index = parentIndex;
            } else {
                break;
            }
        }
    }

    private sinkDown(index: number): void {
        const length = this.heap.length;
        const item = this.heap[index];

        for (let i = 0; i < length; i++) {
            const leftChild = 2 * index + 1;
            const rightChild = 2 * index + 2;
            let swap = false;

            if (leftChild < length && this.heap[leftChild].priority < item.priority) {
                swap = true;
            }
            if (rightChild < length && this.heap[rightChild].priority < (swap ? this.heap[leftChild].priority : item.priority)) {
                swap = true;
            }

            if (swap) {
                this.heap[index] = this.heap[leftChild];
                if (rightChild < length) {
                    this.heap[leftChild] = this.heap[index];
                }
                index = leftChild;
            } else {
                break;
            }
        }
    }
}

